### code

```python
class IntervalMerger:
    def __init__(self) -> None:
        self._intervals: list[tuple[int, int]] = []

    def add(self, start: int, end: int) -> None:
        if start >= end:
            raise ValueError("start must be less than end")
        self._intervals.append((start, end))

    def merge(self) -> list[tuple[int, int]]:
        merged: list[tuple[int, int]] = []

        for start, end in sorted(self._intervals):
            # Coalesce adjacent intervals as well as overlapping ones.
            if merged and start <= merged[-1][1]:
                previous_start, previous_end = merged[-1]
                merged[-1] = (previous_start, max(previous_end, end))
            else:
                merged.append((start, end))

        return merged
```

### tests

Pytest-style functions using only stdlib assertions:

```python
def test_empty():
    assert IntervalMerger().merge() == []


def test_single_interval():
    merger = IntervalMerger()
    merger.add(-3, 2)
    assert merger.merge() == [(-3, 2)]


def test_unsorted_overlapping_nested_and_duplicate_intervals():
    merger = IntervalMerger()
    for interval in [(8, 10), (2, 6), (1, 4), (3, 5), (2, 6)]:
        merger.add(*interval)
    assert merger.merge() == [(1, 6), (8, 10)]


def test_adjacent_intervals():
    merger = IntervalMerger()
    for interval in [(4, 6), (0, 2), (2, 4)]:
        merger.add(*interval)
    assert merger.merge() == [(0, 6)]


def test_negative_and_disjoint_intervals():
    merger = IntervalMerger()
    for interval in [(3, 5), (-5, -2), (-3, 1)]:
        merger.add(*interval)
    assert merger.merge() == [(-5, 1), (3, 5)]


def test_invalid_intervals_do_not_change_state():
    merger = IntervalMerger()
    merger.add(1, 3)

    for start, end in [(1, 1), (3, 1)]:
        try:
            merger.add(start, end)
        except ValueError:
            pass
        else:
            raise AssertionError("Expected ValueError")

    assert merger.merge() == [(1, 3)]


def test_repeated_merge_and_add_after_merge():
    merger = IntervalMerger()
    merger.add(1, 3)
    merger.add(5, 7)
    assert merger.merge() == [(1, 3), (5, 7)]
    assert merger.merge() == [(1, 3), (5, 7)]

    merger.add(2, 6)
    assert merger.merge() == [(1, 7)]


def test_result_mutation_does_not_affect_state():
    merger = IntervalMerger()
    merger.add(1, 3)
    result = merger.merge()
    result.clear()
    assert merger.merge() == [(1, 3)]
```

### complexity

For **n** added intervals:

- `add`: O(1) amortized time.
- `merge`: O(n log n) time and O(n) additional space.
- Stored intervals: O(n) space.
